class Solution { private int[] parent;private int find(int value){if(parent[value]!=value)parent[value]=find(parent[value]);return parent[value];}private void union(int a,int b){parent[find(a)]=find(b);}public List<List<String>> accountsMerge(List<List<String>> accounts){parent=new int[accounts.size()];for(int i=0;i<parent.length;i++)parent[i]=i;Map<String,Integer> owner=new HashMap<>();Map<String,String> names=new HashMap<>();for(int i=0;i<accounts.size();i++)for(int j=1;j<accounts.get(i).size();j++){String email=accounts.get(i).get(j);names.put(email,accounts.get(i).get(0));if(owner.containsKey(email))union(i,owner.get(email));else owner.put(email,i);}Map<Integer,List<String>> groups=new HashMap<>();for(Map.Entry<String,Integer> entry:owner.entrySet())groups.computeIfAbsent(find(entry.getValue()),key->new ArrayList<>()).add(entry.getKey());List<List<String>> answer=new ArrayList<>();for(List<String> emails:groups.values()){Collections.sort(emails);List<String> row=new ArrayList<>();row.add(names.get(emails.get(0)));row.addAll(emails);answer.add(row);}answer.sort(Comparator.comparing(row->row.get(1)));return answer;} }
